/**
 * Registration identifiers.
 *
 * Two identifiers exist for one registration, and they are not interchangeable.
 *
 * 1. `registration_id` — the system-assigned primary key. UUID v4, generated by PostgreSQL's
 *    `gen_random_uuid()` (a core function since PostgreSQL 13, no extension required). The database is
 *    the generator, so two application instances cannot mint the same value and the key is never
 *    assigned by a caller that might retry.
 *
 * 2. `confirmation_reference` — the student-facing identifier, per DATA-MODEL.md line 390 and
 *    FR-REG-020 ("unique to the registration and display it to the student"). MVP.md line 84 records
 *    why it exists: "Lets staff identify a participant verbally." That is the entire design
 *    constraint. It must be short, unambiguous when read aloud or read from a printed list, and must
 *    not disclose a sequence.
 *
 *    The alphabet is Crockford-style, omitting I, L, O and U so that 1/I, 0/O and U/V cannot be
 *    confused in handwriting or speech.
 *
 *    EVERY position varies. An earlier implementation packed a 16-bit value into the 32-symbol
 *    alphabet, which filled only the last four characters and produced references such as
 *    `00007K2M` — a reference that looks like it has four digits of information and does not. Eight
 *    symbols are therefore drawn independently, giving 32^8 = 1,099,511,627,776 combinations.
 *
 *    FR-REG-020 requires uniqueness; no generator can guarantee it. `0001_initial.sql` carries a
 *    UNIQUE constraint, and the two are complementary: the generator makes collisions improbable, the
 *    constraint makes them impossible.
 *
 *    No format for the reference is specified in any source document. This format is recorded as a
 *    project-owner implementation decision in PROJECT-OWNER-DECISIONS.md, not as a documented
 *    requirement.
 *
 * L3 and pure. Entropy arrives as a parameter, so this module imports nothing: the lint rule scoped to
 * `src/domain/**` forbids `node:*`, and reading entropy is I/O. `src/db/identifiers.ts` is the
 * platform-bound binding.
 */

/** Crockford-style: digits and uppercase letters, minus I, L, O and U. */
export const CONFIRMATION_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ" as const;

/** Characters in a reference. One entropy byte is drawn per character. */
export const CONFIRMATION_LENGTH = 8 as const;

/** Compile-time proof that the alphabet is a power of two, which is what makes byte % 32 uniform. */
export const CONFIRMATION_ALPHABET_SIZE = CONFIRMATION_ALPHABET.length as 32;

/** Number of distinct references the generator can produce: 32^8. */
export const CONFIRMATION_SPACE = 32 ** CONFIRMATION_LENGTH;

export class EntropyRangeError extends RangeError {
  constructor(value: number) {
    super(`Entropy byte must be an integer in 0-255, got ${value}`);
    this.name = "EntropyRangeError";
  }
}

/**
 * A source of {@link CONFIRMATION_LENGTH} unbiased byte values, one per reference character.
 *
 * A function rather than an array, so that the caller decides when to draw and tests can script an
 * exact sequence.
 */
export type EntropySource = () => number[];

/**
 * Adapt a single-byte issuer to an {@link EntropySource}.
 *
 * NO REJECTION SAMPLING IS NEEDED, and that is worth stating because the usual advice is to reject.
 * Reduction `byte % 32` is uniform exactly when the modulus divides 256, and 32 divides 256, so all 32
 * outcomes are equally likely with no bias. Rejection sampling would only add a branch that can never
 * trigger. Had the alphabet been, say, 30 symbols, rejection would be mandatory: 256 % 30 = 16, and
 * the first 16 outcomes would be over-represented.
 */
export function entropyFromBytes(issueByte: () => number): EntropySource {
  return () => {
    const bytes: number[] = [];
    for (let i = 0; i < CONFIRMATION_LENGTH; i += 1) {
      const byte = issueByte();
      if (!Number.isInteger(byte) || byte < 0 || byte > 255) {
        throw new EntropyRangeError(byte);
      }
      bytes.push(byte);
    }
    return bytes;
  };
}

/**
 * Map each entropy byte to one alphabet symbol.
 *
 * Exported for testing. Throws when the byte count does not match the reference length, because a
 * short read would silently produce a reference with less entropy than advertised.
 */
export function encodeConfirmationSymbols(bytes: readonly number[]): string {
  if (bytes.length !== CONFIRMATION_LENGTH) {
    throw new RangeError(
      `Expected exactly ${CONFIRMATION_LENGTH} entropy bytes, received ${bytes.length}. ` +
        "A short read would produce a reference with less entropy than its length suggests.",
    );
  }

  let reference = "";
  for (const byte of bytes) {
    if (!Number.isInteger(byte) || byte < 0 || byte > 255) {
      throw new EntropyRangeError(byte);
    }
    reference += CONFIRMATION_ALPHABET[byte % CONFIRMATION_ALPHABET_SIZE];
  }
  return reference;
}

/**
 * Generate a student-facing confirmation reference.
 *
 * `entropy` is required rather than defaulted. Defaulting it would mean importing `node:crypto` into
 * L3, which the layer rule forbids. Binding entropy to the platform is L4's job.
 */
export function generateConfirmationReference(entropy: EntropySource): string {
  return encodeConfirmationSymbols(entropy());
}

/** True when a string is a well-formed reference: the right length, alphabet only. */
export function isWellFormedConfirmationReference(value: string): boolean {
  if (value.length !== CONFIRMATION_LENGTH) {
    return false;
  }
  for (const character of value) {
    if (!CONFIRMATION_ALPHABET.includes(character)) {
      return false;
    }
  }
  return true;
}

/**
 * The character distribution a reference must have for every position to be informative.
 *
 * Exported as a constant rather than inline so that a test asserting uniformity reads as a statement
 * about this design rather than an arbitrary threshold.
 */
export const EXPECTED_DISTINCT_SYMBOLS_PER_POSITION = CONFIRMATION_ALPHABET_SIZE;